 static void Main(string[] args){Directory.CreateDirectory(args[1]);using(var art=new TransformationArt(args[0]))for(int page=0;page<4;page++)using(var atlas=new Bitmap(8*144,8*112))using(var g=Graphics.FromImage(atlas)){g.Clear(Color.FromArgb(32,36,43));for(int item=0;item<64;item++){int id=page*64+item;if(id>=255)break;string path=Path.Combine(Path.GetDirectoryName(args[0]),"gamedata/pzs3us1",(0x2f8+id).ToString("D5")+".bin");if(!File.Exists(path))continue;try{using(var image=TransformationArt.Decode(File.ReadAllBytes(path))){if(Array.IndexOf(new[]{9,25,27,32,66,70,80,102,152,153},id)>=0)image.Save(Path.Combine(args[1],"portrait-"+id+".png"));var crop=art.Crop(id);float h=crop.Width*80/128;crop.Y+=(crop.Height-h)/2;crop.Height=h;int x=(item%8)*144,y=(item/8)*112;g.DrawImage(image,new RectangleF(x,y,128,80),crop,GraphicsUnit.Pixel);g.DrawString(id+" "+art.Name(id),SystemFonts.DefaultFont,Brushes.White,new RectangleF(x,y+80,140,32));}}catch(IOException){Console.WriteLine("No portrait for "+id);}}atlas.Save(Path.Combine(args[1],"portrait-grid-"+page+".png"));}}
